const message = $json;

// --- UTILITY FUNCTIONS ---
function stripPrefix(value, prefix) {
  if (typeof value !== 'string') return value;
  return value.replace(new RegExp('^' + prefix + '\\s*:\\s*', 'i'), '').trim();
}

function extractAddress(field) {
  if (!field) return null;
  const item = Array.isArray(field) ? field[0] : field;
  if (!item) return null;
  if (typeof item === 'object' && item.address) return item.address;
  if (typeof item === 'string' && item.trim()) return item;
  return null;
}

function firstNonEmpty(candidates) {
  for (const c of candidates) {
    const addr = extractAddress(c);
    if (addr) return addr;
  }
  return null;
}

function parseEmailTimestamp(msg) {
  // 1. Try Gmail internalDate (epoch timestamp in ms)
  if (msg.internalDate) {
    const epochMs = Number(msg.internalDate);
    if (!isNaN(epochMs)) return new Date(epochMs).toISOString();
  }
  // 2. Try standard email Date header
  const dateHeader = msg.Date || msg.date || msg.headers?.date || msg.headers?.Date;
  if (dateHeader) {
    const parsedDate = new Date(dateHeader);
    if (!isNaN(parsedDate.getTime())) return parsedDate.toISOString();
  }
  // 3. Fallback to current time if email timestamp is completely missing
  return new Date().toISOString();
}

// --- FIELD EXTRACTION ---
const rawSubject = firstNonEmpty([
  message.Subject,
  message.subject,
  message.headers?.subject,
  message.headers?.Subject
]);

const rawFrom = firstNonEmpty([
  message.From,
  message.from,
  message.headers?.from,
  message.headers?.From
]);

const subject = stripPrefix(rawSubject || 'Statement', 'Subject');
const senderEmail = stripPrefix(rawFrom || 'unknown', 'From');
const snippet = message.snippet || '';

const messageId = message.id || 'unknown';
const emailTimestamp = parseEmailTimestamp(message);

// --- BANK REGISTRY & CONFIGURATION ---
const BANK_REGISTRY = {
  American_Express: {
    sender: ['americanexpress.com', 'aexp.com', 'amex'],
    subject: ['american express', 'smartearn', 'membership rewards', 'platinum travel', 'centurion'],
    snippet: ['american express', 'amex']
  },
  HDFC: {
    sender: ['hdfcbank.net', 'hdfcbank.com', 'hdfcbank'],
    subject: ['hdfc bank', 'diners club', 'regalia', 'millennia', 'infinia'],
    snippet: ['hdfc bank']
  },
  ICICI: {
    sender: ['icicibank.com', 'icicibank.org', 'icicibank'],
    subject: ['icici bank', 'rubyx', 'saphiro', 'amazon pay icici'],
    snippet: ['icici bank']
  },
  Axis: {
    sender: ['axisbank.com', 'axisbank'],
    subject: ['axis bank', 'burgundy', 'magnus', 'vistaracard', 'flipkart axis'],
    snippet: ['axis bank']
  },
  AU_Small_Finance: {
    sender: ['aubank.in', 'aubank.org', 'aubank'],
    subject: ['au small finance', 'zenith', 'vetta', 'altura'],
    snippet: ['au small finance', 'aubank']
  },
  Kotak: {
    sender: ['kotak.com', 'kotakbank'],
    subject: ['kotak mahindra', 'kotak bank'],
    snippet: ['kotak bank']
  },
  YES_Bank: {
    sender: ['yesbank.in', 'yesbank','yes.bank.in'],
    subject: ['yes bank', 'yes prosperity'],
    snippet: ['yes bank']
  },
  IndusInd: {
    sender: ['indusind.com', 'indusind'],
    subject: ['indusind bank'],
    snippet: ['indusind']
  },
  RBL: {
    sender: ['rblbank.com', 'rblbank'],
    subject: ['rbl bank', 'ratnakar bank'],
    snippet: ['rbl bank']
  },
  IDFC_First: {
    sender: ['idfcfirstbank.com', 'idfcbank'],
    subject: ['idfc first bank', 'idfc first'],
    snippet: ['idfc first']
  },
  SBI_Card: {
    sender: ['sbicard.com', 'sbi.co.in'],
    subject: ['sbi card', 'simplyclick', 'simplysave'],
    snippet: ['sbi card']
  },
  Bank_of_Baroda: {
    sender: ['bobcard.co.in', 'bankofbaroda.com'],
    subject: ['bobcard', 'bank of baroda'],
    snippet: ['bobcard']
  }
};

// --- PRE-COMPILED REGEX REGISTRY ---
const COMPILED_REGISTRY = Object.entries(BANK_REGISTRY).map(([bankKey, rules]) => {
  const compile = (patterns = []) =>
    patterns.map(p => new RegExp('\\b' + p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'i'));

  return {
    bankKey,
    senderRegexes: compile(rules.sender),
    subjectRegexes: compile(rules.subject),
    snippetRegexes: compile(rules.snippet),
    rawSenderPatterns: rules.sender,
    rawSubjectPatterns: rules.subject,
    rawSnippetPatterns: rules.snippet
  };
});

// --- WEIGHTS ---
const WEIGHTS = {
  sender: 100, // Dominant authority
  subject: 20,
  snippet: 3
};

/**
 * RESOLUTION ENGINE
 */
function resolveBankWithObservability(sender, subj, snip) {
  let bestMatch = {
    bank_name: 'Unknown',
    confidence: 0,
    detected_from: 'none',
    matched_patterns: {
      sender: null,
      subject: null,
      snippet: null
    }
  };

  for (const entry of COMPILED_REGISTRY) {
    let score = 0;
    let detectedFrom = [];
    let matchedSender = null;
    let matchedSubject = null;
    let matchedSnippet = null;

    // 1. Check Sender (Tier 1 Authority)
    for (let i = 0; i < entry.senderRegexes.length; i++) {
      if (entry.senderRegexes[i].test(sender)) {
        score += WEIGHTS.sender;
        matchedSender = entry.rawSenderPatterns[i];
        detectedFrom.push('sender');
        break; // Match once per category
      }
    }

    // EARLY EXIT SHORTCUT: If sender matched, it is 100% authoritative. Stop checking other banks.
    if (matchedSender) {
      // Still quickly check subject/snippet of THIS bank for observability enrichment
      for (let i = 0; i < entry.subjectRegexes.length; i++) {
        if (entry.subjectRegexes[i].test(subj)) {
          score += WEIGHTS.subject;
          matchedSubject = entry.rawSubjectPatterns[i];
          detectedFrom.push('subject');
          break;
        }
      }
      for (let i = 0; i < entry.snippetRegexes.length; i++) {
        if (entry.snippetRegexes[i].test(snip)) {
          score += WEIGHTS.snippet;
          matchedSnippet = entry.rawSnippetPatterns[i];
          detectedFrom.push('snippet');
          break;
        }
      }

      return {
        bank_name: entry.bankKey,
        confidence: score,
        detected_from: detectedFrom.join('+'),
        matched_patterns: {
          sender: matchedSender,
          subject: matchedSubject,
          snippet: matchedSnippet
        }
      };
    }

    // 2. Check Subject
    for (let i = 0; i < entry.subjectRegexes.length; i++) {
      if (entry.subjectRegexes[i].test(subj)) {
        score += WEIGHTS.subject;
        matchedSubject = entry.rawSubjectPatterns[i];
        detectedFrom.push('subject');
        break;
      }
    }

    // 3. Check Snippet
    for (let i = 0; i < entry.snippetRegexes.length; i++) {
      if (entry.snippetRegexes[i].test(snip)) {
        score += WEIGHTS.snippet;
        matchedSnippet = entry.rawSnippetPatterns[i];
        detectedFrom.push('snippet');
        break;
      }
    }

    if (score > bestMatch.confidence) {
      bestMatch = {
        bank_name: entry.bankKey,
        confidence: score,
        detected_from: detectedFrom.join('+') || 'none',
        matched_patterns: {
          sender: matchedSender,
          subject: matchedSubject,
          snippet: matchedSnippet
        }
      };
    }
  }

  // Minimum threshold: Must reach at least subject level score (>= 20) if sender missed
  if (bestMatch.confidence < WEIGHTS.subject) {
    bestMatch.bank_name = 'Unknown';
  }

  return bestMatch;
}

const detection = resolveBankWithObservability(senderEmail, subject, snippet);

return {
  json: {
    message_id: messageId,
    bank_name: detection.bank_name,
    sender_email: senderEmail,
    subject: subject,
    timestamp: emailTimestamp,
    detection: {
      confidence: detection.confidence,
      detected_from: detection.detected_from,
      matched_patterns: detection.matched_patterns,
      needs_manual_review: detection.confidence < 20 || detection.bank_name === 'Unknown'
    }
  },
  binary: $binary
};

const j = $json;

// Get input raw merchant or description
const raw = String(
  j.merchant ??
  j.merchant_raw ??
  j.description ??
  ""
).trim();

// --------------------------------------------------
// 1. Canonical Merchant Aliases
// --------------------------------------------------
const aliases = [
  [/AMAZON/i, "AMAZON"],
  [/DECATHLON/i, "DECATHLON"],
  [/BIGBASKET/i, "BIGBASKET"],
  [/MYNTRA/i, "MYNTRA"],
  [/ZERODHA/i, "ZERODHA"],
  [/HPCL/i, "HPCL"],
  [/INDIAN\s*OIL|IOCL/i, "IOCL"],
  [/BHARAT\s*PETROLEUM|BPCL/i, "BPCL"],
  [/ULTA/i, "ULTA"],
  [/GAP/i, "GAP"],
  [/MACY/i, "MACYS"],
  [/LYFT/i, "LYFT"],
  [/BATH\s*&\s*BODY|BATH\s*AND\s*BODY/i, "BATHBODYWORKS"],
  [/H&M|H\s*&\s*M/i, "HM"],
  [/DAISO/i, "DAISO"],
  [/COACH/i, "COACH"],
  [/NJTRANSIT|NJ\s*TRANSIT/i, "NJTRANSIT"],
  [/ALASKA\s*AIR|ALASKA\s*A/i, "ALASKAAIR"],
  [/LADERACH/i, "LADERACH"],
  [/SOCIAL/i, "SOCIAL"],
  [/SWIGGY/i, "SWIGGY"],
  [/ZOMATO/i, "ZOMATO"],
  [/STARBUCKS/i, "STARBUCKS"],
  [/DOMINO/i, "DOMINOS"],
  [/UBER/i, "UBER"],
];

// --------------------------------------------------
// 2. Basic cleaning for normalized_merchant
// --------------------------------------------------
function getNormalizedMerchant(value) {
  if (!value) return "UNKNOWN";

  const upper = value.toUpperCase();

  // First check aliases
  for (const [regex, canonical] of aliases) {
    if (regex.test(upper)) {
      return canonical;
    }
  }

  let m = upper;

  // Remove company suffixes
  m = m
    .replace(/\bPRIVATE\s+LIMITED\b/g, " ")
    .replace(/\bPVT\.?\s*LTD\.?\b/g, " ")
    .replace(/\bLIMITED\b/g, " ")
    .replace(/\bLTD\.?\b/g, " ")
    .replace(/\bLLP\b/g, " ")
    .replace(/\bINDIA\b/g, " ");

  // Remove payment noise
  m = m
    .replace(/\bUPI\b/g, " ")
    .replace(/\bPOS\b/g, " ")
    .replace(/\bECOM\b/g, " ")
    .replace(/\bONLINE\b/g, " ")
    .replace(/\bPAYMENT\b/g, " ");

  // Remove store IDs / terminal IDs
  m = m
    .replace(/#\d+/g, " ")
    .replace(/\b\d{3,}\b/g, " ");

  // Remove punctuation
  m = m.replace(/[^A-Z0-9 ]/g, " ");

  // Collapse spaces
  m = m.replace(/\s+/g, " ").trim();

  // Stable lookup key
  m = m.replace(/\s/g, "");

  return m || "UNKNOWN";
}

// --------------------------------------------------
// 3. Extract clean canonical display_name
// --------------------------------------------------
function getDisplayName(rawText, normalizedText) {

  if (!rawText || normalizedText === "UNKNOWN") {
    return "Unknown Merchant";
  }

  const upper = rawText.toUpperCase();

  const displayAliases = [
    [/AMAZON/i, "Amazon"],
    [/DECATHLON/i, "Decathlon"],
    [/BIGBASKET/i, "BigBasket"],
    [/MYNTRA/i, "Myntra"],
    [/ZERODHA/i, "Zerodha"],
    [/HPCL/i, "HPCL"],
    [/INDIAN\s*OIL|IOCL/i, "Indian Oil"],
    [/BHARAT\s*PETROLEUM|BPCL/i, "Bharat Petroleum"],
    [/ULTA/i, "Ulta Beauty"],
    [/GAP/i, "Gap"],
    [/MACY/i, "Macy's"],
    [/LYFT/i, "Lyft"],
    [/BATH\s*&\s*BODY|BATH\s*AND\s*BODY/i, "Bath & Body Works"],
    [/H&M|H\s*&\s*M/i, "H&M"],
    [/DAISO/i, "Daiso"],
    [/COACH/i, "Coach"],
    [/NJTRANSIT|NJ\s*TRANSIT/i, "NJ Transit Rail"],
    [/ALASKA\s*AIR|ALASKA\s*A/i, "Alaska Airlines"],
    [/LADERACH/i, "Läderach"],
    [/SOCIAL/i, "Social"],
    [/SWIGGY/i, "Swiggy"],
    [/ZOMATO/i, "Zomato"],
    [/STARBUCKS/i, "Starbucks"],
    [/DOMINO/i, "Domino's"],
    [/UBER/i, "Uber"],
  ];

  for (const [regex, display] of displayAliases) {
    if (regex.test(upper)) {
      return display;
    }
  }

  return normalizedText
    .replace(/([A-Z])/g, " $1")
    .trim()
    .replace(/\b\w/g, c => c.toUpperCase());
}

const normalized = getNormalizedMerchant(raw);
const displayName = getDisplayName(raw, normalized);

// Return structure matching your target database schema
return {
  json: {
    ...j,
    normalized_merchant: normalized,
    display_name: displayName,
    category: j.category || "Uncategorized",
    confidence: normalized === "UNKNOWN" ? 20 : 90
  }
};

const txn = $('Normalize Merchant').item.json;

// HTTP node returns:
// {
//   body: [ { found:true ... } ],
//   headers:{},
//   statusCode:200
// }

const lookup =
    $json.body && $json.body.length
        ? $json.body[0]
        : null;

return {
  json: {

    ...txn,

    merchant_found: Boolean(lookup?.found),

    merchant_id: lookup?.merchant_id ?? null,

    category:
      lookup?.found
        ? lookup.category
        : txn.category,

    display_name:
      lookup?.found
        ? lookup.display_name
        : txn.display_name,

    confidence:
      lookup?.found
        ? lookup.confidence
        : txn.confidence,

    category_source:
      lookup?.found
        ? "merchant_memory"
        : "ai"
  }
};

