const response = $json;

const text = response.candidates?.[0]?.content?.parts?.[0]?.text;

if (!text) {
  throw new Error("Gemini returned no text.");
}

let ai;

try {
  ai = JSON.parse(text);
} catch (e) {
  throw new Error(`Invalid Gemini JSON:\n${text}`);
}

const original = $("IF Merchant Known").item.json;

return {
  json: {
    ...original,

    display_name:
      ai.display_name ||
      original.display_name ||
      original.merchant,

    normalized_merchant:
      original.normalized_merchant,

    category:
      ai.category ||
      original.category ||
      "Other",

    confidence:
      Number(ai.confidence ?? 50),

    category_source: "ai"
  }
};

const items = $input.all();

const output = [];

for (const item of items) {
  const txns = item.json.transactions || [];

  const statementMonth = new Date()
    .toISOString()
    .split('-')
    .slice(0, 2)
    .join('-');

  for (const txn of txns) {
 output.push({
  json: {
    user_id: "2f324f4d-1dc3-4ec5-8c23-93da480842c7",

    Date: txn.transaction_date,
    Bank: item.json.bank_name,
    'Card Last4': item.json.card_last4,
    'Card Type': 'Credit',

    Merchant: txn.merchant,
    Merchant_Normalized: txn.merchant.toUpperCase(),

    Amount: txn.amount,
    Currency: txn.currency,

    Category: 'Uncategorized',

    'Raw Description': txn.description,

    'Statement Month': statementMonth,

    'Source File': item.json.subject,

    transaction_type: txn.debit_credit,

    confidence: 95
  }
});
  }
}

return output;

// Current transaction
const txn = $input.item.json;

// Merchant cache built earlier
const cache = $("Build Merchant Cache").first().json.merchant_cache || {};

// Normalize lookup key
const key = (txn.normalized_merchant || "")
    .trim()
    .toUpperCase();

// Lookup merchant
const merchant = cache[key];

if (merchant) {

    return {
        json: {

            ...txn,

            merchant_found: true,

            display_name: merchant.display_name,
            category: merchant.category,
            confidence: merchant.confidence,

            category_source: "merchant_memory"

        }
    };

}

// Merchant not found
return {
    json: {

        ...txn,

        merchant_found: false,

        category_source: "ai"

    }
};

const merchantCache = {};

for (const item of $input.all()) {

    const merchant = item.json.normalized_merchant;

    if (!merchant) continue;

    const key = merchant.trim().toUpperCase();

    merchantCache[key] = {
        normalized_merchant: merchant,
        display_name: item.json.display_name,
        category: item.json.category,
        confidence: item.json.confidence
    };

}

return [{
    json: {
        merchant_cache: merchantCache,
        merchant_count: Object.keys(merchantCache).length
    }
}];

const j = $json;

const statementDate = new Date(
  j.timestamp || new Date().toISOString()
);

const statementMonth =
  `${statementDate.getFullYear()}-${String(statementDate.getMonth() + 1).padStart(2, '0')}-01`;

const statementId =
  `${j.message_id}_${statementMonth}`;

return {
  json: {
    message_id: j.message_id,

    bank_name: j.bank_name,
    card_last4: j.card_last4,
    business_personal: j.business_personal,

    sender_email: j.sender_email,
    subject: j.subject,
    timestamp: j.timestamp,

    statement_id: statementId,
    statement_month: statementMonth,

    source_file:
      j.filename ||
      j.file_name ||
      j.attachment_name ||
      null,

    parser_version: "v2",
    extraction_method: "ai"
  }
};

