      data.card_last4 ?? null,

    account_last4:
      data.account_last4 ?? null,

    account_type:
      data.account_type ?? null,

    card_type:
      data.card_type ?? null,

    business_personal:
      data.business_personal ?? null,

    message_id:
      $json.message_id ?? null,

    subject:
      $json.subject ?? null,

    sender_email:
      $json.sender_email ?? null,

    timestamp:
      $json.timestamp ?? null
  },

  binary: $binary
};

return {
  json: {
    message_id: $json.message_id,
    bank_name: $json.bank_name,
    password: $json.password,
    card_last4: $json.card_last4,
    business_personal: $json.business_personal,
    subject: $json.subject,
    sender_email: $json.sender_email,
    timestamp: $json.timestamp
  }
};

// Runs on the MAIN output of "CC Parser API" (fullResponse + neverError means
// both HTTP 200 and HTTP 4xx/5xx land here as { statusCode, headers, body }).
// This node ONLY classifies the HTTP layer. Parse-quality evaluation (native vs
// fallback) happens next, in "Evaluate Parse Quality".
const res = $json;
const statusCode = res.statusCode;
const body = res.body || {};

if (statusCode === 200) {
  // Pass the full new-contract envelope through untouched.
  return {
    json: {
      parse_status: body.parse_status,
      extraction_method: body.extraction_method,
      fallback_available: body.fallback_available,
      fallback_reason: body.fallback_reason,
      parse_quality: body.parse_quality || {},
      bank: body.bank,
      data: body.data,
      raw_text: body.raw_text
      // routing_decision intentionally left unset here -- "Evaluate Parse Quality" sets it.
    }
  };
}

// --- HTTP-level error classification ---
// Exact error body shape wasn't specified beyond the status codes in the API
// contract (422 password_required, 401 invalid_password, 422 unsupported_bank).
// Reads common fields defensively; verify against a real error response and
// adjust the string matching below if field names differ.
const detail = String(body.detail || body.error || body.message || '').toLowerCase();

let errorCategory = 'unexpected_api_error';
if (statusCode === 401) {
  errorCategory = 'invalid_password';
} else if (statusCode === 422 && detail.includes('password')) {
  errorCategory = 'password_required';
} else if (statusCode === 422 && (detail.includes('bank') || detail.includes('unsupported'))) {
  errorCategory = 'unsupported_bank';
} else if (statusCode === 422 || detail.includes('parse') || detail.includes('parsing')) {
  errorCategory = 'pdf_parsing_failure';
}

return {
  json: {
    routing_decision: 'error',
    error_category: errorCategory,
    error_status_code: statusCode ?? null,
    error_message: body.detail || body.error || body.message || 'CC Parser API returned an error response.'
  }
};

// Only fires for genuine connection-level failures (DNS failure, connection
// refused, timeout) via onError:"continueErrorOutput" -- NOT HTTP status codes,
// which are handled on the main output via fullResponse + neverError instead.
const err = $json;
const message =
  (err.error && err.error.message) ||
  err.message ||
  'Could not reach CC Parser API (connection failure).';

return {
  json: {
    routing_decision: 'error',
    error_category: 'http_connection_failure',
    error_status_code: null,
    error_message: message
  }
};

// Single place that decides native vs fallback vs error, based on the
// documented contract:
//   Native:   parse_status == "success" AND parse_quality.status == "pass"
//   Fallback: parse_status == "fallback_required" OR parse_quality.status in
//             ("review","fail")  -- AND fallback_available AND raw_text present
//   Error:    anything else (including fallback claimed but raw_text missing)
//
// If "Classify Parser Response" / "Classify Connection Failure" already set
// routing_decision:'error' (an HTTP-level or connection-level failure), that
// decision is authoritative and is NOT re-evaluated here.
const j = $json;

if (j.routing_decision === 'error') {
  return { json: j };
}

const pq = j.parse_quality || {};
let decision = 'error';

if (j.parse_status === 'success' && pq.status === 'pass') {
  decision = 'native';
} else if (
  j.parse_status === 'fallback_required' ||
  pq.status === 'review' ||
  pq.status === 'fail'
) {
  decision = (j.fallback_available && j.raw_text) ? 'fallback' : 'error';
}

const out = { ...j, routing_decision: decision };

if (decision === 'error' && !out.error_category) {
  out.error_category = j.fallback_available
    ? 'pdf_parsing_failure'        // fallback claimed available but raw_text missing
    : 'pdf_parsing_failure';       // parse_quality failed and no fallback offered
  out.error_message = out.error_message
    || `parse_quality.status="${pq.status}", fallback_available=${j.fallback_available}, raw_text_present=${Boolean(j.raw_text)}`;
}

return { json: out };

parameters.jsonBody:
={
  "system_instruction": {
    "parts": [
      {
        "text": "You are a deterministic, bank-agnostic bank/credit-card statement transaction extractor. You are NOT a categorizer. Extract every transaction present in the provided raw statement text. Never invent a transaction that is not in the text. Never drop a transaction because the merchant looks unfamiliar. Preserve debit vs credit, dates, amounts, narration, and payment/refund rows exactly as stated. Return ONLY valid strict JSON. No markdown. No explanations. No text outside the JSON object."
      }
    ]
  },
  "generationConfig": {
    "temperature": 0,
    "topP": 0.1,
    "topK": 1,
    "maxOutputTokens": 8192,
    "responseMimeType": "application/json"
  },
  "contents": [
    {
      "parts": [
        {
          "text": "Extract every transaction from this bank/credit-card statement.\n\nContext (for reference only -- do not let it override what the text actually says):\nBank: {{ $json.bank || $('Extract Password for Bank').item.json.bank_name }}\nEmail subject: {{ $('Extract Password for Bank').item.json.subject }}\nSender email: {{ $('Extract Password for Bank').item.json.sender_email }}\n\nRAW STATEMENT TEXT:\n{{ $json.raw_text }}\n\nRules:\n1. Extract ALL transactions: purchases, payments, refunds, credits, fees, reversals. Set row_type to payment_refund for payment/refund rows and transaction for everything else.\n2. transaction_date MUST be YYYY-MM-DD. Infer the year from statement context if ambiguous; never omit the date.\n3. amount MUST be a plain JSON number, e.g. 1249.00, never a quoted string like 1,249.00.\n4. debit_credit MUST be exactly debit or credit.\n5. Do not invent transactions. Do not skip a transaction because the merchant is unrecognized -- copy the narration as-is into merchant and description.\n6. If a field genuinely is not present in the text, use null. Never fabricate a value.\n\nReturn EXACTLY this JSON shape and nothing else -- no markdown, no commentary:\n{\"bank\":string|null,\"statement_total_amount_due\":number|null,\"transactions\":[{\"transaction_date\":\"YYYY-MM-DD\",\"time\":string|null,\"merchant\":string,\"description\":string,\"amount\":number,\"debit_credit\":\"debit|credit\",\"transaction_type\":string|null,\"row_type\":\"transaction|payment_refund\",\"reference_number\":string|null,\"card_last4\":string|null,\"person\":string|null,\"reward_points\":number|null,\"credit_reasons\":string|null}]}\n\nThe first character of your response must be {. The last character must be }."
        }
      ]
    }
  ]
}

parameters.jsCode:
// Never throws -- a bad/missing response is recorded as a soft failure and
// flows through "Validate AI Output" -> "AI Validation Gate" -> "Flag For Review"
// like any other validation failure, instead of killing the execution here.
const text = $json.candidates?.[0]?.content?.parts?.[0]?.text;

let parsed = null;
let parseError = null;

if (!text) {
  parseError = 'gemini_no_text_returned';
} else {
  try {
    parsed = JSON.parse(text);
  } catch (e) {
    parseError = 'gemini_invalid_json';
  }
}

return {
  json: {
    gemini_output: parsed,
    gemini_parse_error: parseError
  }
};

// AI OUTPUT VALIDATION -- the hard gate between Gemini and the rest of the
// pipeline. Nothing from Gemini is trusted until it passes every check below.
//
// This is also the ONE place in the whole workflow that computes a reconciliation
// delta with an explicit tolerance (native trusts the API's own
// parse_quality.reconciliation_status directly and never recomputes this).
const CENTRAL_RECONCILIATION_TOLERANCE = 1; // currency units -- tune against real data

const j = $json;
const reasons = [];

if (j.gemini_parse_error) {
  return {
    json: {
      ai_validation_status: 'review',
      ai_validation_reasons: [j.gemini_parse_error],
      reconciliation_status: 'unknown',
      transactions: [],
      statement_total_amount_due: null,
      bank: null
    }
  };
}

const output = j.gemini_output || {};
const txns = Array.isArray(output.transactions) ? output.transactions : [];

if (txns.length === 0) reasons.push('zero_transactions');

const dateRe = /^\d{4}-\d{2}-\d{2}$/;
const seenRefs = new Set();
let duplicateRefs = false;
let missingRequired = false;

for (const t of txns) {
  if (!t.transaction_date || !dateRe.test(t.transaction_date)) { missingRequired = true; reasons.push('missing_dates'); }
  if (typeof t.amount !== 'number' || Number.isNaN(t.amount)) { missingRequired = true; reasons.push('missing_or_bad_amount'); }
  if (!t.merchant && !t.description) { missingRequired = true; reasons.push('empty_narration'); }
  if (t.debit_credit !== 'debit' && t.debit_credit !== 'credit') { missingRequired = true; reasons.push('missing_debit_credit'); }
  if (t.reference_number) {
    if (seenRefs.has(t.reference_number)) duplicateRefs = true;
    seenRefs.add(t.reference_number);
  }
}
if (duplicateRefs) reasons.push('duplicate_transaction_ids');

// Centralized reconciliation decision (AI-fallback path only).
let reconciliationStatus = 'reconciliation_unknown';
if (typeof output.statement_total_amount_due === 'number' && txns.length > 0) {
  const computedTotal = txns
    .filter(t => t.debit_credit === 'debit')
    .reduce((sum, t) => sum + (Number(t.amount) || 0), 0);
  const delta = Math.abs(computedTotal - output.statement_total_amount_due);
  reconciliationStatus = delta <= CENTRAL_RECONCILIATION_TOLERANCE ? 'pass' : 'fail';
  if (reconciliationStatus === 'fail') reasons.push('reconciliation_failed');
} else {
  reasons.push('reconciliation_unknown');
}

const hardFail = missingRequired || txns.length === 0;
const status = hardFail ? 'review' : (reconciliationStatus === 'fail' ? 'review' : 'pass');

return {
  json: {
    ai_validation_status: status,
    ai_validation_reasons: [...new Set(reasons)],
    reconciliation_status: reconciliationStatus,
    transactions: txns,
    statement_total_amount_due: output.statement_total_amount_due ?? null,
    bank: output.bank ?? null
  }
};

// Maps VALIDATED Gemini output into the exact same canonical per-transaction
// shape "Structured Transactions" (native path) produces, so both paths
// converge into one schema before "Merge Statement + PDF".
const messageId = $('Extract Password for Bank').item.json.message_id;
const txns = $json.transactions || [];
const fallbackReason = ($('Evaluate Parse Quality').item.json.fallback_reason) || null;

const mapped = txns.map(t => ({
  transaction_date: t.transaction_date,
  message_id: messageId,
  merchant: t.merchant || t.description || '',
  description: t.description || t.merchant || '',
  amount: t.amount,
  debit_credit: t.debit_credit,
  transaction_type: t.transaction_type || (t.row_type === 'payment_refund' ? 'payment_refund' : null),
  reference_number: t.reference_number || null,
  reward_points: t.reward_points ?? null,
  person: t.person ?? null,
  credit_reasons: t.credit_reasons ?? null,
  time: t.time ?? null,
  card_number: t.card_last4 ?? null,
  category_hint: null, // Gemini fallback never produces a native category_hint
  extraction_method: 'ai_fallback',
  parse_quality_status: $json.ai_validation_status || 'pass',
  fallback_reason: fallbackReason
}));

return {
  json: {
    statement_total: $json.statement_total_amount_due ?? null,
    statement_txn_count: mapped.length,
    transactions: mapped
  }
};

// ============================================================
// STRUCTURED TRANSACTIONS
// Native CC Parser path
// One input statement -> one n8n item per transaction
// ============================================================

const input = $input.first().json;

const passwordMeta =
  $('Extract Password for Bank').first().json;

const data = input.data || {};

const parseQualityStatus =
  input.parse_quality?.status || 'pass';

// ------------------------------------------------------------
// Source arrays
// ------------------------------------------------------------

const transactions = Array.isArray(data.transactions)
  ? data.transactions
  : [];

const paymentsRefunds = Array.isArray(data.payments_refunds)
  ? data.payments_refunds
  : [];

const messageId =
  passwordMeta.message_id || null;

// ------------------------------------------------------------
// Determine account/card type
//
// Priority:
// 1. Explicit metadata from Extract Password for Bank
// 2. Parser account_type
// 3. Presence of card number/card last4
//
// Credit-card statements:
//   card_last4   = populated
//   account_last4 = null
//
// Savings/current statements:
//   card_last4   = null
//   account_last4 = populated
// ------------------------------------------------------------

const explicitAccountType =
  passwordMeta.account_type ||
  data.account_type ||
  null;

const hasCardNumber =
  Boolean(data.card_number);

const hasCardLast4 =
  Boolean(passwordMeta.card_last4);

const normalizedAccountType =
  String(explicitAccountType || '').trim().toLowerCase();

const isSavings =
  normalizedAccountType === 'savings' ||
  normalizedAccountType === 'savings account';

const isCurrent =
  normalizedAccountType === 'current' ||
  normalizedAccountType === 'current account';

const isExplicitCreditCard =
  normalizedAccountType === 'credit card' ||
  normalizedAccountType === 'creditcard' ||
  normalizedAccountType === 'credit_card';

const isCardStatement =
  isExplicitCreditCard ||
  (!isSavings && !isCurrent && (hasCardNumber || hasCardLast4));

let accountType;

if (isCardStatement) {
  accountType = 'Credit Card';
} else if (isSavings) {
  accountType = 'Savings';
} else if (isCurrent) {
  accountType = 'Current';
} else {
  accountType = explicitAccountType || null;
}

// ------------------------------------------------------------
// Card / account last 4
// ------------------------------------------------------------

const parserCardLast4 =
  data.card_number
    ? String(data.card_number).slice(-4)
    : null;

const parserAccountLast4 =
  data.account_number
    ? String(data.account_number).slice(-4)
    : null;

const cardLast4 = isCardStatement
  ? (
      passwordMeta.card_last4 ||
      parserCardLast4 ||
      null
    )
  : null;

const accountLast4 = !isCardStatement
  ? (
      passwordMeta.account_last4 ||
      parserAccountLast4 ||
      null
    )
  : null;

// ------------------------------------------------------------
// Card type
// ------------------------------------------------------------

const cardType = isCardStatement
  ? (
      passwordMeta.card_type ||
      'Credit'
    )
  : null;

// ------------------------------------------------------------
// Statement-level metadata
// ------------------------------------------------------------

const statementMonth =
  data.statement_month || null;

const statementId =
  statementMonth && messageId
    ? `${messageId}_${statementMonth}`
    : null;

const statementMetadata = {
  statement_id: statementId,

  statement_month: statementMonth,

  statement_period_start:
    data.statement_period_start || null,

  statement_period_end:
    data.statement_period_end || null,

  due_date:
    data.due_date || null,

  source_file:
    data.file || null,

  bank_name:
    passwordMeta.bank_name ||
    data.bank ||
    null,

  parser_bank:
    data.bank || null,

  card_last4: cardLast4,

  account_last4: accountLast4,

  card_type: cardType,

  account_type: accountType,

  business_personal:
    passwordMeta.business_personal || null,

  sender_email:
    passwordMeta.sender_email || null,

  subject:
    passwordMeta.subject || null,

  timestamp:
    passwordMeta.timestamp || null,

  parser_version:
    input.parser_version || 'v4'
};

// ------------------------------------------------------------
// Helpers
// ------------------------------------------------------------

function mapDebitCredit(type) {
  const t = String(type || '').toLowerCase();

  if (
    t.includes('credit') ||
    t.includes('refund') ||
    t.includes('payment')
  ) {
    return 'credit';
  }

  if (
    t.includes('debit') ||
    t.includes('purchase')
  ) {
    return 'debit';
  }

  return null;
}

function buildTransaction(txn, fallbackType = null) {
  return {
    ...statementMetadata,

    // --------------------------------------------------------
    // Transaction fields
    // --------------------------------------------------------

    transaction_date:
      txn.date || null,

    merchant:
      txn.narration || '',

    description:
      txn.narration || '',

    amount:
      txn.amount ?? null,

    currency:
      txn.currency || 'INR',

    debit_credit:
      mapDebitCredit(txn.transaction_type) ||
      fallbackType ||
      null,

    transaction_type:
      txn.transaction_type ||
      fallbackType ||
      null,

    reference_number:
      txn.transaction_id || null,

    reward_points:
      txn.reward_points ?? null,

    person:
      txn.person ?? null,

    credit_reasons:
      txn.credit_reasons ?? null,

    time:
      txn.time ?? null,

    // For cards, keep card number.
    // For savings/current, use account number if parser provides it.
    card_number:
      isCardStatement
        ? (
            txn.card_number ||
            data.card_number ||
            null
          )
        : null,

    account_number:
      !isCardStatement
        ? (
            txn.account_number ||
            data.account_number ||
            null
          )
        : null,

    category_hint:
      txn.category_hint ??
      data.category_hint ??
      data.default_category_hint ??
      null,

    // --------------------------------------------------------
    // Audit fields
    // --------------------------------------------------------

    extraction_method:
      'native',

    parse_quality_status:
      parseQualityStatus,

    fallback_reason:
      null
  };
}

// ------------------------------------------------------------
// Build debit transactions
// ------------------------------------------------------------

const normalizedTransactions =
  transactions.map(txn =>
    buildTransaction(txn)
  );

// ------------------------------------------------------------
// Build payments / refunds
// ------------------------------------------------------------

const normalizedPaymentsRefunds =
  paymentsRefunds.map(pr =>
    buildTransaction(pr, 'credit')
  );

// ------------------------------------------------------------
// Combine
// ------------------------------------------------------------

const allTransactions = [
  ...normalizedTransactions,
  ...normalizedPaymentsRefunds
];

// ------------------------------------------------------------
// IMPORTANT:
// Run Once for All Items -> return array of n8n items
// ------------------------------------------------------------

return allTransactions.map(transaction => ({
  json: transaction
}));

// Priority tier 2: merchant wasn't in memory, but the native parser already
// supplied a deterministic category_hint -- use it instead of calling Gemini.
// (Deliberately NOT written to merchant memory here -- a hint is a per-statement
// suggestion, not a confirmed merchant categorization. Easy to add later if wanted.)
const j = $json;
return {
  json: {
    ...j,
    display_name: j.display_name || j.merchant || 'Unknown Merchant',
    category: j.category_hint,
    confidence: j.category_hint_confidence ?? 70,
    category_source: 'parser_category_hint'
  }
};

// Shared failure handler for: a hard CC Parser error/connection failure, a
// failed AI-output validation, or a failed final-transaction validation.
// There is still no dedicated review/error queue in the Supabase schema, so
// this throws a descriptive error -- full context lands in the n8n Execution
// log, which is where failures already show up today. If a persistent review
// queue is wanted later, the smallest addition is one Supabase table plus an
// insert step here instead of throwing.
const j = $json;

let stage = 'unknown';
let reason = 'unclassified failure';
let detail = null;

if (j.validation_status === 'fail') {
  stage = 'final_validation';
  reason = (j.validation_missing_fields || []).join(', ') || 'required fields missing';
  detail = j.validation_missing_fields || null;
} else if (j.ai_validation_status === 'review') {
  stage = 'ai_validation';
  reason = (j.ai_validation_reasons || []).join(', ') || 'ai validation failed';
  detail = j.ai_validation_reasons || null;
} else if (j.routing_decision === 'error') {
  stage = 'parsing';
  reason = j.error_category || 'unexpected_api_error';
  detail = j.error_message || null;
}

const ctx = $('Extract Password for Bank').item.json;

const context = {
  stage,
  message_id: ctx.message_id || null,
  bank_name: ctx.bank_name || null,
  subject: ctx.subject || null,
  timestamp: ctx.timestamp || null,
  reason,
  detail
};

throw new Error(`Bank statement flagged for review [${context.stage}]: ${context.reason} -- ${JSON.stringify(context)}`);

// The final hard gate. No required financial field may be null, and a
// missing amount is NEVER treated as 0 -- it fails validation instead.
const j = $json;
const REQUIRED_FIELDS = ['user_id', 'bank_name', 'transaction_date', 'amount', 'currency', 'merchant', 'transaction_type', 'category', 'status'];

const missing = REQUIRED_FIELDS.filter(f => j[f] === null || j[f] === undefined || j[f] === '');

if (typeof j.amount !== 'number' || Number.isNaN(j.amount)) {
  if (!missing.includes('amount')) missing.push('amount');
}

return {
  json: {
    ...j,
    validation_status: missing.length === 0 ? 'pass' : 'fail',
    validation_missing_fields: missing
  }
};

// ============================================================
// THE ONE TEST-MODE SWITCH FOR THIS WORKFLOW.
// TEST_MODE = true  -> rows are validated and shown, but NEVER inserted into Supabase.
// TEST_MODE = false -> rows go to Supabase as normal (production).
// Flip this one constant when you're ready to go live -- nothing else to change.
// ============================================================
const TEST_MODE = true;

return { json: { ...$json, TEST_MODE } };

// TEST_MODE is on -- this row was validated but deliberately NOT sent to
// Supabase. Inspect it in the execution output, then flip TEST_MODE to false
// in "Test Mode Config" when you're ready to go live.
const { TEST_MODE, ...row } = $json;
return {
  json: {
    test_mode: true,
    note: 'TEST_MODE is enabled -- this row was NOT inserted into Supabase.',
    would_insert: row
  }
};

const bankName = $json.bank_name;

const parserBankMap = {
  HDFC: 'hdfc',
  ICICI: 'icici',
  Axis: 'axis',
  SBI_Card: 'sbi',
  YES_Bank: 'yes_bank',
  AU_Small_Finance: 'zenith_au'
};

const parser_bank = parserBankMap[bankName];

if (!parser_bank) {
  throw new Error(`No CC Parser bank mapping for: ${bankName}`);
}

return {
  json: {
    ...$json,
    parser_bank
  },
  binary: $binary
};
